// Emergency stop check
const stopFlag = ($env.AUTOPILOT_STOP || '').toLowerCase();
if (stopFlag === 'true') {
  return [{ json: { emergency_stop: true, reason: 'AUTOPILOT_STOP=true' } }];
}
return [{ json: { emergency_stop: false } }];

// Gather environment status
const status = {
  autopilot_social: ($env.AUTOPILOT_SOCIAL_POSTING || 'false').toLowerCase() === 'true',
  has_buffer: !!$env.BUFFER_API_KEY,
  has_metricool: !!$env.METRICOOL_API_KEY,
  has_meta_token: !!$env.META_ACCESS_TOKEN,
  has_tiktok_token: !!$env.TIKTOK_ACCESS_TOKEN,
  has_whatsapp: !!$env.WHATSAPP_ACCESS_TOKEN,
  has_telegram: !!$env.TELEGRAM_CHAT_ID,
  max_posts: {
    tiktok: parseInt($env.MAX_TIKTOK_POSTS_PER_DAY || '1'),
    instagram: parseInt($env.MAX_INSTAGRAM_POSTS_PER_DAY || '1'),
    facebook: parseInt($env.MAX_FACEBOOK_POSTS_PER_DAY || '1')
  },
  today: new Date().toISOString().split('T')[0],
  timestamp: new Date().toISOString()
};

status.has_any_posting_api = status.has_buffer || status.has_metricool || status.has_meta_token || status.has_tiktok_token;

return [{ json: status }];

// Process social posts: find pending/approved posts for today
// Apply safety: max posts per platform, no duplicates within 24h
const envStatus = $('Gather Environment Status').first().json;
const allPosts = $('Read Social Posts').all().map(i => i.json);
const today = envStatus.today;
const maxPosts = envStatus.max_posts || { tiktok: 1, instagram: 1, facebook: 1 };

// Filter today's posts
const todayPosts = allPosts.filter(p => p.date === today);
const pendingPosts = todayPosts.filter(p => p.status === 'approved' || p.autopilot_status === 'pending' || p.autopilot_status === 'ready_manual');

// Count already posted today per platform
const postedToday = {};
todayPosts.forEach(p => {
  if (p.autopilot_status === 'scheduled' || p.autopilot_status === 'published') {
    postedToday[p.platform] = (postedToday[p.platform] || 0) + 1;
  }
});

// Check for duplicates (same caption within last 24h)
const recentCaptions = allPosts
  .filter(p => {
    const pDate = new Date(p.date);
    const now = new Date();
    return (now - pDate) < 86400000;
  })
  .map(p => p.caption ? p.caption.toLowerCase().trim() : '');

const readyToPost = [];
const blocked = [];

for (const post of pendingPosts) {
  const platformCount = postedToday[post.platform] || 0;
  const platformMax = maxPosts[post.platform] || 1;
  const captionLower = (post.caption || '').toLowerCase().trim();
  const isDuplicate = recentCaptions.filter(c => c === captionLower).length > 1;

  if (platformCount >= platformMax) {
    blocked.push({ ...post, block_reason: 'max_posts_reached' });
  } else if (isDuplicate) {
    blocked.push({ ...post, block_reason: 'duplicate_within_24h' });
  } else {
    readyToPost.push(post);
    postedToday[post.platform] = platformCount + 1;
  }
}

return [{
  json: {
    ...envStatus,
    total_posts_today: todayPosts.length,
    pending_posts: pendingPosts.length,
    ready_to_post: readyToPost,
    blocked_posts: blocked,
    ready_count: readyToPost.length,
    blocked_count: blocked.length
  }
}];

// Process WhatsApp leads needing follow-up
// Safety: never spam, only follow up leads with follow_up_status=pending
// and last_message older than 24 hours
const allLeads = $('Read Leads').all().map(i => i.json);
const allConvos = $('Read WhatsApp Conversations').all().map(i => i.json);
const today = new Date();
const twentyFourHoursAgo = new Date(today - 86400000);

// Find leads needing follow-up
const needsFollowUp = allLeads.filter(lead => {
  if (lead.status === 'unsubscribed') return false;
  if (lead.source !== 'whatsapp') return false;

  // Check if last message is older than 24h
  const lastMsg = lead.last_message ? new Date(lead.last_message) : null;
  if (!lastMsg || lastMsg > twentyFourHoursAgo) return false;

  // Check conversation isn't complete
  if (lead.status === 'converted' || lead.status === 'completed') return false;

  return true;
});

// Today's stats
const todayStr = today.toISOString().split('T')[0];
const leadsToday = allLeads.filter(l => l.first_contact && l.first_contact.startsWith(todayStr));
const convosToday = allConvos.filter(c => c.timestamp && c.timestamp.startsWith(todayStr));

return [{
  json: {
    leads_needing_followup: needsFollowUp,
    followup_count: needsFollowUp.length,
    total_leads: allLeads.length,
    leads_today: leadsToday.length,
    conversations_today: convosToday.length,
    unsubscribed_count: allLeads.filter(l => l.status === 'unsubscribed').length
  }
}];

// Schedule approved posts via available API
const data = $('Process Social Posts').first().json;
const posts = data.ready_to_post || [];

if (posts.length === 0) {
  return [{ json: { action: 'no_posts_to_schedule', count: 0 } }];
}

// Determine posting API
let apiName = 'none';
if (data.has_buffer) apiName = 'buffer';
else if (data.has_metricool) apiName = 'metricool';
else if (data.has_meta_token) apiName = 'meta';
else if (data.has_tiktok_token) apiName = 'tiktok';

const scheduled = posts.map((post, i) => ({
  ...post,
  autopilot_status: 'scheduled',
  posting_api: apiName,
  scheduled_at: new Date(Date.now() + (i + 1) * 3600000).toISOString()
}));

return scheduled.map(s => ({ json: s }));

// Send WhatsApp follow-ups to leads with pending status
// Safety: only message users who messaged first, not unsubscribed, max 1 follow-up per 24h
const leadsData = $('Process WhatsApp Leads').first().json;
const leads = leadsData.leads_needing_followup || [];
const hasWhatsApp = !!$env.WHATSAPP_ACCESS_TOKEN;

if (!hasWhatsApp || leads.length === 0) {
  return [{ json: { action: 'no_followups', count: 0, reason: !hasWhatsApp ? 'no_whatsapp_token' : 'no_leads_pending' } }];
}

// Limit to max 10 follow-ups per run to avoid spam
const maxFollowups = Math.min(leads.length, 10);
const toFollowUp = leads.slice(0, maxFollowups);

return toFollowUp.map(lead => ({
  json: {
    phone: lead.phone,
    name: lead.name || 'there',
    user_type: lead.user_type || 'friend',
    followup_message: `Hi ${lead.name || 'there'}! 👋 Just checking in from Eki. We noticed you were interested in our AI automation platform. Ready to take the next step? Download our app: ${$env.APP_DOWNLOAD_LINK || 'https://eki.app'}\n\nReply STOP to unsubscribe.`
  }
}));

// Build daily summary for Telegram
const social = $('Process Social Posts').first().json;
const leads = $('Process WhatsApp Leads').first().json;
const today = new Date().toISOString().split('T')[0];

const summary = {
  date: today,
  leads_captured_today: leads.leads_today,
  total_leads: leads.total_leads,
  posts_generated: social.total_posts_today,
  posts_scheduled: social.ready_to_post ? social.ready_to_post.filter(p => p.autopilot_status === 'scheduled').length : 0,
  posts_ready_manual: social.ready_count,
  posts_blocked: social.blocked_count,
  whatsapp_conversations_today: leads.conversations_today,
  followups_sent: leads.followup_count,
  unsubscribed: leads.unsubscribed_count,
  errors: social.blocked_posts ? social.blocked_posts.map(b => b.platform + ': ' + b.block_reason).join(', ') : 'none',
  autopilot_social: social.autopilot_social,
  has_posting_api: social.has_any_posting_api
};

return [{ json: summary }];

